/**
 * Runtime side of the NCP <-> Showdown name maps (generated by scripts/build-bridge).
 */
import { loadGenData, normalizeSearch } from '../data'
import type { GenData } from '../data'
import { prepare } from '../engine'
import { GEN_META, genMeta, type BridgeGenMeta } from './gens'
import {
  FLAG_ALIAS,
  FLAG_FOREIGN,
  FLAG_GMAX,
  FLAG_NATDEX_ONLY,
  FLAG_NCP_ONLY,
  type BridgeMapFile,
  type DataGenId,
  type EntityKind,
  type MapEntry,
} from './types'

const mapLoaders = import.meta.glob<{ default: BridgeMapFile }>('./generated/*.json')

export const ENTITY_KINDS: readonly EntityKind[] = ['species', 'moves', 'items', 'abilities']

export interface KindIndex {
  /** Bridge (Showdown-style) id -> entry. Includes alias and Gigantamax entries. */
  byId: Map<string, MapEntry>
  /** NCP name -> primary entry (aliases and Gigantamax entries excluded). */
  byNcp: Map<string, MapEntry>
}

export interface Bridge {
  gen: DataGenId
  meta: BridgeGenMeta
  map: BridgeMapFile
  data: GenData
  kinds: Record<EntityKind, KindIndex>
  /** Showdown records by id (moves: by id of the English name, see `nameKey`). */
  records: Record<EntityKind, Map<string, { id: string; en: string; de: string }>>
}

export const isNatDexOnly = (e: MapEntry) => (e[2] & FLAG_NATDEX_ONLY) !== 0
export const isNcpOnly = (e: MapEntry) => (e[2] & FLAG_NCP_ONLY) !== 0
export const isGmax = (e: MapEntry) => (e[2] & FLAG_GMAX) !== 0
export const isAlias = (e: MapEntry) => (e[2] & FLAG_ALIAS) !== 0
export const isForeign = (e: MapEntry) => (e[2] & FLAG_FOREIGN) !== 0
/** True for entries that are distinct NCP entities (not one-way aliases / Gigantamax). */
export const isPrimary = (e: MapEntry) => (e[2] & (FLAG_ALIAS | FLAG_GMAX)) === 0

function buildBridge(map: BridgeMapFile, data: GenData): Bridge {
  const kinds = {} as Record<EntityKind, KindIndex>
  const records = {} as Bridge['records']
  for (const kind of ENTITY_KINDS) {
    const byId = new Map<string, MapEntry>()
    const byNcp = new Map<string, MapEntry>()
    for (const e of map[kind]) {
      byId.set(e[0], e)
      if (isPrimary(e)) byNcp.set(e[1], e)
    }
    kinds[kind] = { byId, byNcp }
    // Typed Hidden Power records share the id "hiddenpower"; their English names differ.
    const recs = new Map<string, { id: string; en: string; de: string }>()
    for (const r of data[kind]) {
      const key = normalizeSearch(r.en)
      if (!recs.has(key)) recs.set(key, r)
    }
    for (const r of data[kind]) if (!recs.has(r.id)) recs.set(r.id, r)
    records[kind] = recs
  }
  return { gen: map.gen, meta: genMeta(map.gen), map, data, kinds, records }
}

const cache = new Map<DataGenId, Promise<Bridge>>()
const loaded = new Map<DataGenId, Bridge>()

/** Loads (once) the name map and entity data of a generation. */
export function loadBridge(gen: DataGenId): Promise<Bridge> {
  let p = cache.get(gen)
  if (!p) {
    const loader = mapLoaders[`./generated/${gen}.json`]
    if (!loader || !GEN_META[gen]) {
      return Promise.reject(new Error(`No bridge map for "${gen}". Run npm run build:bridge.`))
    }
    p = Promise.all([loader(), loadGenData(gen)]).then(([m, data]) => {
      const b = buildBridge(m.default, data)
      loaded.set(gen, b)
      return b
    })
    p.catch(() => cache.delete(gen))
    cache.set(gen, p)
  }
  return p
}

/** Loads the bridge of `gen` and prepares the engine for it. Await before using the sync API. */
export async function prepareBridge(gen: DataGenId): Promise<Bridge> {
  const [bridge] = await Promise.all([loadBridge(gen), prepare(GEN_META[gen].engineGen)])
  return bridge
}

/** The loaded bridge; throws if `loadBridge`/`prepareBridge` has not completed for `gen`. */
export function getBridge(gen: DataGenId): Bridge {
  const b = loaded.get(gen)
  if (!b) throw new Error(`Bridge for "${gen}" not loaded: await prepareBridge("${gen}") first`)
  return b
}

/** NCP name for a Showdown id, or undefined if the engine does not know the entity. */
export function ncpName(gen: DataGenId, kind: EntityKind, id: string): string | undefined {
  return getBridge(gen).kinds[kind].byId.get(id)?.[1]
}

/** Showdown id for an NCP name (the primary id; `ncp-only` entities get their normalized name). */
export function showdownId(gen: DataGenId, kind: EntityKind, ncp: string): string | undefined {
  return getBridge(gen).kinds[kind].byNcp.get(ncp)?.[0]
}

export interface EntityNames {
  en: string
  /** Undefined when only the NCP English name is known (NCP-only entities). */
  de: string | undefined
}

export function entityNames(b: Bridge, kind: EntityKind, id: string): EntityNames | undefined {
  const rec = b.records[kind].get(id)
  if (rec) return { en: rec.en, de: rec.de }
  const e = b.kinds[kind].byId.get(id)
  if (!e) return undefined
  if (e.length === 5) return { en: e[3], de: e[4] }
  return { en: e[1], de: undefined }
}
